func TestFilesService_Add_WithFormField(t *testing.T) {
	t.Parallel()

	client := newTestClient(t, func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			t.Fatalf("unexpected method: %s", r.Method)
		}
		if r.URL.Path != "/files" {
			t.Fatalf("unexpected path: %s", r.URL.Path)
		}

		ct := r.Header.Get("Content-Type")
		_, params, err := mime.ParseMediaType(ct)
		if err != nil {
			t.Fatalf("parse media type: %v", err)
		}
		mr := multipart.NewReader(r.Body, params["boundary"])

		var dealID, fileName string
		for {
			part, err := mr.NextPart()
			if err == io.EOF {
				break
			}
			if err != nil {
				t.Fatalf("next part: %v", err)
			}
			switch part.FormName() {
			case "deal_id":
				b, _ := io.ReadAll(part)
				dealID = string(b)
			case "file":
				fileName = part.FileName()
			}
		}
		if dealID != "42" {
			t.Fatalf("unexpected deal_id: %q", dealID)
		}
		if fileName != "doc.txt" {
			t.Fatalf("unexpected file name: %q", fileName)
		}

		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"success":true,"data":{"id":13,"name":"doc.txt"}}`))
	})

	file, err := client.Files.Add(context.Background(), "doc.txt", strings.NewReader("x"), WithFilesFormField("deal_id", "42"))
	if err != nil {
		t.Fatalf("Add error: %v", err)
	}
	if file.ID != 13 {
		t.Fatalf("unexpected file: %#v", file)
	}
}

func TestFilesService_Add_RetriesOn429(t *testing.T) {
	t.Parallel()

	policy := pipedrive.DefaultRetryPolicy()
	policy.MaxAttempts = 3
	policy.BaseDelay = time.Millisecond
	policy.MaxDelay = time.Millisecond

	var calls int
	client := newTestClientWithConfig(t, pipedrive.Config{RetryPolicy: &policy}, func(w http.ResponseWriter, r *http.Request) {
		calls++
		_, _ = io.Copy(io.Discard, r.Body)

		if calls <= 2 {
			w.WriteHeader(http.StatusTooManyRequests)
			_, _ = w.Write([]byte(`{"success":false,"error":"rate limited"}`))
			return
		}

		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"success":true,"data":{"id":12,"name":"upload.txt"}}`))
	})

	file, err := client.Files.Add(context.Background(), "doc.txt", strings.NewReader("file-content"))
	if err != nil {
		t.Fatalf("Add error: %v", err)
	}
	if calls != 3 {
		t.Fatalf("expected 3 calls, got %d", calls)
	}
	if file.ID != 12 {
		t.Fatalf("unexpected file: %#v", file)
	}
}

